/*
  # Tabela TACO (4ª edição revisada e ampliada, NEPA/UNICAMP, 2011)

  593 alimentos (4 da tabela original ficaram de fora por não terem energia nem macronutrientes), valores por 100 g da parte comestível. Campos sem análise ou com
  traço na tabela original entram como 0 (sódio fica nulo). Medidas caseiras só nos alimentos
  mais comuns; o app sempre permite informar a quantidade em gramas.
  O campo nutrients traz umidade, kJ, cinzas, colesterol, gorduras (saturada, mono, poli e trans),
  minerais e vitaminas; nutriente não analisado fica fora do objeto.
  Fonte dos dados convertidos: github.com/raulfdm/taco-api (MIT), extraídos do PDF oficial.
  Pode ser executado mais de uma vez: atualiza pelo taco_id.
*/

ON CONFLICT (taco_id) DO UPDATE SET
  name = EXCLUDED.name,
  category = EXCLUDED.category,
  kcal = EXCLUDED.kcal,
  protein = EXCLUDED.protein,
  carbs = EXCLUDED.carbs,
  fat = EXCLUDED.fat,
  fiber = EXCLUDED.fiber,
  sodium = EXCLUDED.sodium,
  nutrients = EXCLUDED.nutrients,
  measures = EXCLUDED.measures;
